import{_ as a,c as e,a as t,aS as o}from"./chunks/framework.BB9D2qGO.js";const b=JSON.parse('{"title":"07-关税相关","description":"","frontmatter":{},"headers":[],"relativePath":"note/knowledge/07-关税相关.md","filePath":"note/knowledge/07-关税相关.md","lastUpdated":1754921361000}'),p={name:"note/knowledge/07-关税相关.md"},r=o('<h1 id="_07-关税相关" tabindex="-1">07-关税相关 <a class="header-anchor" href="#_07-关税相关" aria-label="Permalink to &quot;07-关税相关&quot;">​</a></h1><blockquote><p>最近中国和美国的关税战打的很火热，新闻上都是在说这个的，我对对关税没什么概念，有很多的疑问点，就在网上查了下资料。 如果有哪里说的不对的地方，欢迎评论讨论。</p></blockquote><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>比如中国华为手机出口到美国。成本价100美元，利润20美元，出口价120美元，原来的美国关税是5%，后面关税增加30%。如何看待呢？</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><h3 id="关税如何计算" tabindex="-1">关税如何计算？ <a class="header-anchor" href="#关税如何计算" aria-label="Permalink to &quot;关税如何计算？&quot;">​</a></h3><p>出口价*税率 = 120美元 × 5% = 6美元</p><h3 id="关税是由谁出的钱" tabindex="-1">关税是由谁出的钱？ <a class="header-anchor" href="#关税是由谁出的钱" aria-label="Permalink to &quot;关税是由谁出的钱？&quot;">​</a></h3><p>美国进口商承担。关税：120美元 × 5% = 6美元。国际运费、保险等（假设10美元）。总成本 = 120 + 6 + 10 = 136美元</p><p>当然，由谁承担这事也不是绝对的，主要是靠双方合同是如何界定的。只能说一般情况下是由进口商承担的。</p><h3 id="什么是出口价" tabindex="-1">什么是出口价？ <a class="header-anchor" href="#什么是出口价" aria-label="Permalink to &quot;什么是出口价？&quot;">​</a></h3><p>出口价通常是 离岸价（FOB），仅包含中国出口商的成本和利润，不含关税、国际运费、美国本地税费等。例如：生产成本：100美元 利润：20美元。出口价（FOB上海）：120美元 出口商定价时通常不主动包含关税，因为关税是进口国政策变量，且由进口商支付。</p><h3 id="关税提高之后的变化" tabindex="-1">关税提高之后的变化 <a class="header-anchor" href="#关税提高之后的变化" aria-label="Permalink to &quot;关税提高之后的变化&quot;">​</a></h3><p><strong>原有关税：5% → 加征后总关税35%。</strong></p><p>华为手机出口价：120美元（FOB上海）。</p><p>美国进口商原总成本：120 + (120×5%) = 126美元。</p><p>加征后总成本：120 + (120×35%) = 162美元。</p><p><strong>可能结果</strong></p><ol><li><p>中国出口商不降价</p><p>美国进口商面临两种选择：</p><p>提高售价：若将零售价从150美元涨至186美元，可能导致销量下降。</p><p>自行消化成本：利润从150 - 126 = 24美元降至150 - 162 = -12美元（亏损）。</p><p>结局：进口商可能停止采购，华为退出美国市场。</p></li><li><p>中国出口商降价分担关税</p><p>假设出口商将价格从120美元降至100美元：</p><p>进口商总成本 = 100 + (100×35%) = 135美元。</p><p>华为利润从20美元（120 - 100）降至0美元（100 - 100）。</p><p>结局：华为利润归零，但可暂时维持市场份额，长期不可持续。</p></li><li><p>转移产业链规避关税</p><p>华为将手机组装转移到越南（对美关税0%），再出口至美国：</p><p>越南生产成本105美元（略高于中国）。</p><p>出口价125美元 → 进口商总成本 = 125 + (125×0%) = 125美元。</p><p>结局：中国损失就业和税收，但企业保住美国市场。</p></li></ol>',19),l=[r];function n(i,h,s,d,c,_){return t(),e("div",null,l)}const m=a(p,[["render",n]]);export{b as __pageData,m as default};
